import Foundation

/// A lenient base64url DECODE, used only for parsing an `L1:` wire's own fields (PLAN.md 3.48.1/3.48.6).
///
/// `Base64Url.decode` (the shared E1/keyring codec) rejects a trailing partial group whose unused low bits are
/// not zero — the right call for OUR OWN key material, where a non-canonical tail would mean a different encoder
/// had a bug worth surfacing. The `L1:` wire is different: `vectors-l1.json` (generated by the Web client's
/// `atob`-based decoder, which performs no such check) includes vectors like a 22-character id of all `E`s —
/// valid, intentional test input — specifically to pin that every platform accepts what `atob` accepts. Matching
/// that oracle is PLAN.md 3.48.6's whole point, so this file is its own, independent decoder rather than a
/// change to the shared one: the strict codec still protects everything it always protected, and this one only
/// ever touches relay wires.
///
/// Encoding needs no lenient counterpart — `Base64Url.encode` always emits the canonical, zero-padded form the
/// vectors expect, which is exactly what every encode vector already confirms.
enum RelayBase64Url {
    private static let lookup: [Int8] = {
        let alphabet = Array("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_".utf8)
        var table = [Int8](repeating: -1, count: 128)
        for (index, char) in alphabet.enumerated() { table[Int(char)] = Int8(index) }
        return table
    }()

    /// nil only for the wrong character set or an impossible length (`len % 4 == 1`) — never for an otherwise
    /// valid string whose last partial byte carries non-zero padding bits.
    static func decode(_ text: String) -> [UInt8]? {
        let chars = Array(text.utf8)
        let len = chars.count
        if len % 4 == 1 { return nil }
        let full = len / 4
        let rest = len % 4
        var out = [UInt8]()
        out.reserveCapacity(full * 3 + (rest == 2 ? 1 : rest == 3 ? 2 : 0))
        var i = 0
        for _ in 0..<full {
            var n = 0
            for _ in 0..<4 {
                guard let v = value(chars[i]) else { return nil }
                n = (n << 6) | v
                i += 1
            }
            out.append(UInt8((n >> 16) & 0xff)); out.append(UInt8((n >> 8) & 0xff)); out.append(UInt8(n & 0xff))
        }
        if rest == 2 {
            guard let a = value(chars[i]), let b = value(chars[i + 1]) else { return nil }
            out.append(UInt8(((a << 2) | (b >> 4)) & 0xff))
        } else if rest == 3 {
            guard let a = value(chars[i]), let b = value(chars[i + 1]), let c = value(chars[i + 2]) else { return nil }
            out.append(UInt8(((a << 2) | (b >> 4)) & 0xff))
            out.append(UInt8(((b << 4) | (c >> 2)) & 0xff))
        }
        return out
    }

    private static func value(_ c: UInt8) -> Int? {
        guard c < 128 else { return nil }
        let v = lookup[Int(c)]
        return v < 0 ? nil : Int(v)
    }
}
